import{_ as t,o as s,c as r,j as a,a as o}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/shidai-sanbuqu/41-序.md","filePath":"books/shidai-sanbuqu/41-序.md","lastUpdated":1792645508000}'),n={name:"books/shidai-sanbuqu/41-序.md"};function l(d,e,i,c,p,u){return s(),r("div",null,[...e[0]||(e[0]=[a("h3",{id:"序",tabindex:"-1"},[o("序 "),a("a",{class:"header-anchor",href:"#序","aria-label":'Permalink to "序"'},"​")],-1),a("p",null,"这本书里将要谈到的是有趣。其实每一本书都应该有趣，对于一些书来说，有趣是它存在的理由；对于另一些书来说，有趣是它应达到的标准。我能记住自己读过的每一本有趣的书，而无趣的书则连书名都不会记得。但是不仅是我，大家都快要忘记有趣是什么了。",-1),a("p",null,"我以为有趣像一个历史阶段，正在被超越。照我的理解，马尔库塞（Herbert Marcuse）在他卓越的著作《单向度的人》里，也表达过相同的看法。当然，中国人的遭遇和他们是不同的故事。在我们这里，智慧被超越，变成了“暧昧不清”；性爱被超越，变成了“思无邪”；有趣被超越之后，就会变成庄严滞重。我们的灵魂将被净化，被提升，而不是如马尔库塞所说的那样，淹没在物欲里。我正等待着有一天，自己能够打开一本书不再期待它有趣，只期待自己能受到教育。与此同时，我也想起了《浮士德》里主人公感到生命离去时所说的话：你真美呀，请等一等！我哀惋正在失去的东西。",-1),a("p",null,"一本小说里总该有些纯属虚构的地方。熟悉数学方面典故的读者一定知道有关费尔马定理的那个有趣的故事，这方面毋庸作者赘言。最近，哈佛大学的一位教授证明了费尔马定理。需要说明的是，书中王二证明费尔马定理，是在此事之前。",-1),a("p",null,"作者",-1)])])}const b=t(n,[["render",l]]);export{m as __pageData,b as default};
